function admin_log(PDO $pdo,array $user,string $action,string $type,int $entity,string $description): void {
 $q=$pdo->prepare('INSERT INTO activity_logs(user_id,action_key,entity_type,entity_id,description,ip_address) VALUES(?,?,?,?,?,?)');
 $q->execute([(int)$user['id'],$action,$type,$entity,$description,$_SERVER['REMOTE_ADDR']??null]);
}
